def tokenize(text: str) -> list[str]:
    """Tokenizes string by space, preserving quoted substrings and handles escaped quotes."""
    tokens = []
    current = []
    in_quotes = False
    for char in text:
        if char == '"':
            in_quotes = not in_quotes
        elif char == ' ' and not in_quotes:
            if current:
                tokens.append(''.join(current))
                current = []
        else:
            current.append(char)
    if current:
        tokens.append(''.join(current))
    return tokens

def sort_tasks(tasks: list[dict]) -> list[dict]:
    """Sort tasks by priority descending (high > medium > low) then deadline ascending."""
    priority_order = {'high': 1, 'medium': 2, 'low': 3}
    return sorted(tasks, key=lambda t: (priority_order.get(t['priority'], 99), t['deadline']))

